do $argentina$
declare
 lid constant uuid := '5c2e00b7-391d-4630-bba1-fd8887fb9c39';
 clubs uuid[] := array['06ebd739-7cc7-4cfb-9b20-14acb39fbc4b','3617b1c3-d22d-457b-8740-855086b99c52','44e20cab-1815-4d71-a943-0733a4fdc377','493dd967-2f76-4d1b-97b4-fe0301bb113c','54d597a0-ecf1-4a5f-9674-4a84f580533c','64194c72-d593-4e09-8d8b-7e3d79e34276','6f1ef03e-9794-4327-9c09-b49e644eff7f','7b96d6cc-97f2-4b2b-9c21-e2980e5356f3','93ebb134-24d4-447d-9252-b45ef5403f46','9cdd59c7-928a-4b65-8544-fb3701afd135','a3d553a9-fe1e-4d89-a95f-339a1aab2106','ac46a861-efcd-4707-be7d-b694990dc05c','ae5a06eb-9f00-4058-9d29-c5c7306ef637','d81e6e25-9f94-492d-a635-c17bbb7fcd36','e1252fbb-461b-4e64-9214-4f2d49a61889','e7cd8a94-b125-4449-840c-7557b492bf27','e9eee4dd-f560-4e2f-a5aa-7ed2f7ea5456','f61d016d-45d4-44e8-b650-aca5f8cd9974','fafe3d53-ea35-45ac-85d9-8437d0f66e6d','fca0b404-b098-419c-afa2-5852adc96814']::uuid[];
begin
 if not exists(select 1 from pg_temp.ld1_legacy_leagues where id=lid and name='Argentina Women’s Basketball League' and country='Argentina' and active)
 or exists(select 1 from pg_temp.ld1_leagues where id=lid and (name is distinct from 'Argentina Women’s Basketball League' or country is distinct from 'Argentina' or season is distinct from '2026-27' or basketball_type is distinct from 'womens' or active is not true))
 or exists(select 1 from pg_temp.ld1_leagues where id<>lid and country='Argentina' and basketball_type='womens' and lower(name) in ('argentina women’s basketball league','liga femenina','liga nacional femenina'))
 or (select count(*) from pg_temp.ld1_teams t join (values ('06ebd739-7cc7-4cfb-9b20-14acb39fbc4b'::uuid,'Independiente Neuquén Women'),('3617b1c3-d22d-457b-8740-855086b99c52'::uuid,'Instituto Women'),('44e20cab-1815-4d71-a943-0733a4fdc377'::uuid,'Boca Juniors Women'),('493dd967-2f76-4d1b-97b4-fe0301bb113c'::uuid,'Náutico Sportivo Avellaneda Women'),('54d597a0-ecf1-4a5f-9674-4a84f580533c'::uuid,'El Biguá Women'),('64194c72-d593-4e09-8d8b-7e3d79e34276'::uuid,'Obras Basket Women'),('6f1ef03e-9794-4327-9c09-b49e644eff7f'::uuid,'Quilmes Women'),('7b96d6cc-97f2-4b2b-9c21-e2980e5356f3'::uuid,'Unión Bahía Women'),('93ebb134-24d4-447d-9252-b45ef5403f46'::uuid,'Deportivo Berazategui Women'),('9cdd59c7-928a-4b65-8544-fb3701afd135'::uuid,'Rocamora Women'),('a3d553a9-fe1e-4d89-a95f-339a1aab2106'::uuid,'Chañares Women'),('ac46a861-efcd-4707-be7d-b694990dc05c'::uuid,'Hindú Club Córdoba Women'),('ae5a06eb-9f00-4058-9d29-c5c7306ef637'::uuid,'Unión Florida Women'),('d81e6e25-9f94-492d-a635-c17bbb7fcd36'::uuid,'Vélez Sarsfield Women'),('e1252fbb-461b-4e64-9214-4f2d49a61889'::uuid,'Sociedad Española Women'),('e7cd8a94-b125-4449-840c-7557b492bf27'::uuid,'Ferro Carril Oeste Women'),('e9eee4dd-f560-4e2f-a5aa-7ed2f7ea5456'::uuid,'Regatas San Nicolás Women'),('f61d016d-45d4-44e8-b650-aca5f8cd9974'::uuid,'Peñarol Mar del Plata Women'),('fafe3d53-ea35-45ac-85d9-8437d0f66e6d'::uuid,'San José Mendoza Women'),('fca0b404-b098-419c-afa2-5852adc96814'::uuid,'El Talar Women')) e(id,name) on t.id=e.id and t.name=e.name join pg_temp.ld1_legacy_teams w on w.id=t.id and w.name=t.name and w.country=t.country where t.country='Argentina' and t.basketball_type='womens' and t.active and t.league_name='Argentina Women’s Basketball League' and (t.league_id is null or t.league_id=lid) and w.league_id=lid and w.active)<>20
 or exists(select 1 from pg_temp.ld1_teams where active and basketball_type='womens' and country='Argentina' and (league_name='Argentina Women’s Basketball League' or league_id=lid) and id<>all(clubs))
 or exists(select 1 from pg_temp.ld1_legacy_teams where active and league_id=lid and id<>all(clubs))
 or exists(select 1 from pg_temp.ld1_memberships where league_id=lid and season='2026-27' and (team_id<>all(clubs) or active is not true))
 then raise exception 'Argentina identity or legacy mirror changed; review required';end if;
 insert into pg_temp.ld1_leagues(id,name,country,season,basketball_type,active) values(lid,'Argentina Women’s Basketball League','Argentina','2026-27','womens',true) on conflict(id) do nothing;
 update pg_temp.ld1_teams set league_id=lid where id=any(clubs) and league_id is null;
 insert into pg_temp.ld1_memberships(id,team_id,league_id,season,active) select gen_random_uuid(),id,lid,'2026-27',true from unnest(clubs) id on conflict(team_id,league_id,season) do nothing;
 if (select count(*) from pg_temp.ld1_teams where league_id=lid and active)<>20 or (select count(*) from pg_temp.ld1_memberships where league_id=lid and season='2026-27' and active)<>20 then raise exception 'Argentina roster mismatch';end if;
end $argentina$;
